arduino.setup:
Serial.begin(9600);
pinMode(${DO}, INPUT);
Serial.println("LDR Sensor Ready");

arduino.loop:
int analog_${COMP_SUFFIX} = analogRead(${AO});
int digital_${COMP_SUFFIX} = digitalRead(${DO});
float lux_${COMP_SUFFIX} = (1023.0 - analog_${COMP_SUFFIX}) / 1023.0 * 1000.0;
Serial.print("LDR Analog: ");
Serial.print(analog_${COMP_SUFFIX});
Serial.print(" | Lux~");
Serial.print(lux_${COMP_SUFFIX}, 0);
Serial.print(" | Dark: ");
Serial.println(digital_${COMP_SUFFIX} == HIGH ? "YES" : "no");
delay(300);
